/**
 * Whether a file looks generated, and why: the reason is shown to the model,
 * which judges the rest. Tuned for recall - a false positive costs one line
 * of warning, a miss costs a regeneration that reverts a rename.
 *
 *   .gitattributes  linguist-generated (declared by the repository)
 *   Go convention   `// Code generated … DO NOT EDIT.` (golang.org/s/generatedcode)
 *   file header     comment lines before the first code line naming the file
 *                   generated (@generated, do not edit, auto-generated, …),
 *                   as GitHub Linguist does
 *   file name       well-known generator outputs (*.pb.go, *_pb.ts, *.gen.ts, …)
 */

import { open } from "node:fs/promises";
import { basename, join, relative } from "node:path";
import { git } from "./snapshot.ts";

const HEADER_BYTES = 4096;
const GO_CONVENTION = /^\/\/ Code generated .* DO NOT EDIT\.$/;
const HEADER_PATTERNS = [/@generated\b/i, /\bdo not edit\b/i, /\bdo not modify\b/i, /\bauto-?generated\b/i, /\bgenerated by\b/i, /\bcode generated\b/i];
const COMMENT_LINE = /^\s*(\/\/|\/\*|\*|#|--|<!--|;;)/;
const NAME_PATTERNS = [
  /\.pb\.go$/,
  /_grpc\.pb\.go$/,
  /\.pb\.gw\.go$/,
  /_pb\.(ts|js|d\.ts)$/,
  /_pb2(_grpc)?\.pyi?$/,
  /\.pb\.(ts|js|cc|h|rs)$/,
  /[._]gen\.(go|ts|tsx|js|rs)$/,
  /\.generated\.(ts|tsx|js|go|rs)$/,
  /_string\.go$/,
  /^mock_.*\.go$/,
];

/** Files of the list that look generated, each with the reason. */
export async function generatedFiles(root: string, inGit: boolean, files: readonly string[]): Promise<Map<string, string>> {
  const reasons = new Map<string, string>();
  if (files.length === 0) {
    return reasons;
  } else {
    if (inGit) {
      for (const file of await linguistGenerated(root, files)) {
        reasons.set(file, ".gitattributes marks it linguist-generated");
      }
    } else {
      // no repository attributes outside git
    }
    await Promise.all(
      files
        .filter((file) => !reasons.has(file))
        .map(async (file) => {
          const reason = (await headerReason(file)) ?? nameReason(file);
          if (reason !== undefined) {
            reasons.set(file, reason);
          } else {
            // looks hand-written
          }
        }),
    );
    return reasons;
  }
}

async function linguistGenerated(root: string, files: readonly string[]): Promise<string[]> {
  const inside = files.filter((file) => !relative(root, file).startsWith(".."));
  if (inside.length === 0) {
    return [];
  } else {
    const output = await git(root, ["check-attr", "-z", "linguist-generated", "--", ...inside.map((file) => relative(root, file))]);
    // -z: path NUL attribute NUL value NUL ...
    const fields = output.split("\0");
    const marked: string[] = [];
    for (let index = 0; index + 2 < fields.length; index += 3) {
      const value = fields[index + 2];
      if (value === "true" || value === "set") {
        marked.push(join(root, fields[index]));
      } else {
        // unset, unspecified or false
      }
    }
    return marked;
  }
}

async function headerReason(file: string): Promise<string | undefined> {
  const handle = await open(file, "r").catch(() => undefined);
  if (handle === undefined) {
    return undefined;
  } else {
    let text: string;
    try {
      const buffer = Buffer.alloc(HEADER_BYTES);
      const { bytesRead } = await handle.read(buffer, 0, HEADER_BYTES, 0);
      text = buffer.subarray(0, bytesRead).toString("utf8");
    } finally {
      await handle.close();
    }
    for (const line of text.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (GO_CONVENTION.test(trimmed) || (COMMENT_LINE.test(line) && HEADER_PATTERNS.some((pattern) => pattern.test(trimmed)))) {
        return `its header says ${JSON.stringify(trimmed.slice(0, 120))}`;
      } else if (trimmed === "" || COMMENT_LINE.test(line) || trimmed.startsWith("#!") || trimmed === '"use strict";') {
        // still in the header
      } else {
        // the first code line ends the header; Go puts the marker anywhere before package, but
        // generators emit it first
        return undefined;
      }
    }
    return undefined;
  }
}

function nameReason(file: string): string | undefined {
  const name = basename(file);
  const pattern = NAME_PATTERNS.find((candidate) => candidate.test(name));
  if (pattern !== undefined) {
    return `its name matches the generator output pattern ${pattern.source}`;
  } else {
    return undefined;
  }
}
